<?php require_once 'includes/../includes/header.php'; $id=(int)($_GET['id']??0);$stmt=$pdo->prepare('SELECT * FROM foods WHERE id=?');$stmt->execute([$id]);$food=$stmt->fetch();if(!$food)redirect('foods.php');$categories=$pdo->query('SELECT * FROM categories ORDER BY category_name')->fetchAll();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['food_name']??'');$description=trim($_POST['description']??'');$category=(int)($_POST['category_id']??0);$price=(float)($_POST['price']??0);$image=trim($_POST['image']??'');$availability=isset($_POST['availability'])?1:0;if(!$name||!$description||!$category||$price<=0||!filter_var($image,FILTER_VALIDATE_URL))$error='Please complete the fields and use a valid image URL.';else{$update=$pdo->prepare('UPDATE foods SET category_id=?,food_name=?,description=?,price=?,image=?,availability=? WHERE id=?');$update->execute([$category,$name,$description,$price,$image,$availability,$id]);redirect('foods.php');}}$page_title='Edit Food'; ?><div class="form-shell"><h1>Edit food</h1><?php if($error): ?><p class="error"><?=esc($error)?></p><?php endif; ?><form method="post"><label>Food name<input name="food_name" value="<?=esc($food['food_name'])?>" required></label><label>Category<select name="category_id" required><?php foreach($categories as $category): ?><option value="<?=$category['id']?>" <?=$food['category_id']==$category['id']?'selected':''?>><?=esc($category['category_name'])?></option><?php endforeach; ?></select></label><label>Description<textarea name="description" required><?=esc($food['description'])?></textarea></label><label>Price<input type="number" name="price" min="1" step="0.01" value="<?=$food['price']?>" required></label><label>Image URL<input type="url" name="image" value="<?=esc($food['image'])?>" required></label><label><input type="checkbox" name="availability" <?=$food['availability']?'checked':''?> style="width:auto"> Available</label><button type="submit">Update Food</button> <a class="button secondary" href="foods.php">Cancel</a></form></div><?php include 'includes/footer.php'; ?>